rules:
rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    match /links/{shortCode} {
      allow read: if true;
      allow create: if request.resource.data.shortCode is string && request.resource.data.originalUrl is string && request.resource.data.clicks == 0;
      allow update: if true;
      allow delete: if false;
    }
  }
}
